let input = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => {
  input += chunk;
});
process.stdin.on('end', () => {
  const words = input.split(/\s+/).filter(Boolean);
  console.log(words.length);
});

const test = require('node:test');
const assert = require('node:assert');
const { execFileSync } = require('node:child_process');
const path = require('node:path');

const wc = (input) =>
  execFileSync('node', [path.join(__dirname, 'wc.js')], { input, encoding: 'utf8' }).trim();

test('counts words separated by mixed whitespace', () => {
  assert.strictEqual(wc('hello  world\n\tfoo bar\n'), '4');
});

test('prints zero for empty input', () => {
  assert.strictEqual(wc(''), '0');
});
